  {"id": "dog-strangling-vine", "name": "Dog-strangling Vine", "sci": "Vincetoxicum rossicum", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Twining vine 1-2 m long", "habitat": "Fields, forest edges, ravines, and disturbed ground.", "tips": "Twining stems with opposite oval leaves and small dark pink star-shaped flowers; slender pods release fluffy seeds.", "fact": "Forms smothering mats and lures monarchs to lay eggs that cannot survive, harming their populations.", "seasons": ["summer"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Aggressive invasive that smothers native vegetation; report infestations and avoid spreading the seeds.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "garlic-mustard", "name": "Garlic Mustard", "sci": "Alliaria petiolata", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant 30-100 cm tall", "habitat": "Shaded forests, trail edges, and floodplains.", "tips": "Look for small four-petalled white flowers over toothed heart-shaped leaves that smell of garlic when crushed.", "fact": "This biennial carpets woodland floors and releases chemicals that suppress native wildflowers and tree seedlings.", "seasons": ["spring"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Aggressive forest invasive; pull and bag plants before they set seed to help stop its spread.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "japanese-knotweed", "name": "Japanese Knotweed", "sci": "Reynoutria japonica", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant 1-3 m tall", "habitat": "Roadsides, riverbanks, and disturbed urban sites.", "tips": "Hollow bamboo-like reddish stems, broad shovel-shaped leaves, and sprays of creamy flowers in late summer.", "fact": "Ranked among the world's worst invasive plants; it regrows from tiny root or stem fragments.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Aggressive invasive whose roots damage pavement and foundations; never compost or move cuttings, which resprout.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "phragmites", "name": "Phragmites (European Common Reed)", "sci": "Phragmites australis subsp. australis", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌾", "size": "Plant 2-5 m tall", "habitat": "Roadside ditches, marshes, shorelines, and wet disturbed ground.", "tips": "Look for towering dense stands of tan stems topped by large fluffy purplish-brown seed plumes, choking out other wetland plants.", "fact": "Considered one of Ontario's worst invasive plants; it spreads by seed and creeping runners to form vast monocultures.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Aggressive wetland invader that crowds out native plants and degrades fish and wildlife habitat; do not cut and move stems, which can resprout and spread it.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "poison-ivy", "name": "Poison Ivy", "sci": "Toxicodendron radicans", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Low plant or climbing vine, variable", "habitat": "Woodland edges, trails, shorelines, and fencerows.", "tips": "Remember 'leaves of three, let it be', glossy leaflets in threes, often reddish in spring and fall.", "fact": "Grows as ground cover, low shrub, or hairy climbing vine, so its form can be deceptive.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Native", "atRisk": false, "caution": "Urushiol oil in all parts causes an itchy, blistering rash on contact; never touch it or breathe smoke from burning it.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "purple-loosestrife", "name": "Purple Loosestrife", "sci": "Lythrum salicaria", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🪻", "size": "Plant 1-2 m tall", "habitat": "Marshes, wet ditches, and shorelines.", "tips": "Tall showy spikes of magenta flowers rising in dense stands over wetlands in mid to late summer.", "fact": "A single plant can release millions of seeds a year, crowding out native marsh vegetation.", "seasons": ["summer"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Aggressive wetland invader that displaces native plants and degrades marsh habitat, do not plant or spread it.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "stinging-nettle", "name": "Stinging Nettle", "sci": "Urtica dioica", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant 0.6-2 m tall", "habitat": "Rich moist soils, floodplains, thickets, and disturbed ground.", "tips": "Toothed opposite leaves and square stems covered in fine stinging hairs; often grows in dense patches.", "fact": "Cooked young leaves are a nutritious edible once heat destroys the sting, but handle only with gloves.", "seasons": ["spring", "summer"], "activity": "varies", "seen": "common", "status": "Native", "atRisk": false, "caution": "Stinging hairs inject irritants that cause burning and welts on contact; wear gloves and long sleeves.", "region": "Province-wide", "angling": ""},
  {"id": "wild-parsnip", "name": "Wild Parsnip", "sci": "Pastinaca sativa", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant 0.5-1.5 m tall", "habitat": "Roadsides, ditches, fields, and disturbed open ground.", "tips": "Look for flat-topped clusters of small yellow flowers on grooved stems in summer, often lining roadsides.", "fact": "An escaped cultivated parsnip now spreading aggressively along Ontario roadways.", "seasons": ["summer"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Sap on skin plus sunlight causes severe burns and blistering (phytophotodermatitis); wear cover and wash exposed skin.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "giant-hogweed", "name": "Giant Hogweed", "sci": "Heracleum mantegazzianum", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant up to 5 m tall", "habitat": "Streambanks, roadsides, ravines, and damp waste ground.", "tips": "Enormous umbrella-like white flower heads on thick purple-blotched, bristly stems, do not touch to identify.", "fact": "A regulated invasive in Ontario; report sightings to authorities rather than trying to remove it yourself.", "seasons": ["summer"], "activity": "varies", "seen": "uncommon", "status": "Invasive", "atRisk": false, "caution": "Watery sap causes severe burns and blistering in sunlight and can cause permanent eye damage; keep well away.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "poison-sumac", "name": "Poison Sumac", "sci": "Toxicodendron vernix", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Shrub/small tree 2-6 m tall", "habitat": "Bogs, swamps, and other wet, boggy ground.", "tips": "Wetland shrub with smooth-edged compound leaves, red stems, and drooping clusters of whitish berries.", "fact": "Distinguished from harmless red-berried sumacs by its white, hanging berries and swampy habitat.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Urushiol causes a severe blistering rash, even worse than poison ivy, never touch or burn it.", "region": "Scattered wetlands in southern Ontario", "angling": ""},
  {"id": "spotted-water-hemlock", "name": "Spotted Water Hemlock", "sci": "Cicuta maculata", "cat": "plants", "sub": "dangerous-invasive", "emoji": "🌿", "size": "Plant 1-2 m tall", "habitat": "Marshes, wet meadows, ditches, and streambanks.", "tips": "Umbrella-shaped clusters of tiny white flowers on purple-streaked stems; leaf veins end in the notches, not the tips.", "fact": "Easily mistaken for edible wild carrot or parsnip, which makes it especially dangerous to foragers.", "seasons": ["summer"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "One of North America's most poisonous plants, a small amount can be fatal if eaten; do not handle or forage nearby.", "region": "Province-wide", "angling": ""},
  // ---- Insects (75) ----
  {"id": "clouded-sulphur", "name": "Clouded sulphur", "sci": "Colias philodice", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 3.5-5.5 cm", "habitat": "Clover and alfalfa fields, roadsides, lawns and any open, weedy ground; larvae feed on legumes.", "tips": "Lemon-yellow wings with a solid black border above (yellow spots in that border on females) and a small dark cell spot; frequently seen puddling at damp soil.", "fact": "Some females occur in a whitish 'alba' form, and males see an ultraviolet wing pattern invisible to us that helps them tell their species from the similar orange sulphur.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "eastern-comma", "name": "Eastern comma", "sci": "Polygonia comma", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 4.5-6.5 cm", "habitat": "Deciduous woods, riverbanks, swamp edges and gardens; larvae feed on nettles, hops and elm.", "tips": "Ragged-edged orange wings with black spots; the dead-leaf underside bears a small silver-white comma mark (a curved hook with swollen ends) at its centre.", "fact": "Adults overwinter and rarely visit flowers, preferring tree sap, rotting fruit and dung, and can be seen basking on warm late-winter days.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "eastern-tailed-blue", "name": "Eastern tailed-blue", "sci": "Cupido comyntas", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 2-3 cm", "habitat": "Short-grass fields, lawns, trail edges and disturbed weedy ground; larvae feed on clovers and other small legumes.", "tips": "Tiny; males powder-blue above, females greyer, both with a pale grey underside sprinkled with black dots and one or two orange spots above a very short thread-like hindwing tail.", "fact": "This is one of the few blues with true tails, and the caterpillars are often tended by ants that feed on their sugary secretions in exchange for protection.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "great-spangled-fritillary", "name": "Great spangled fritillary", "sci": "Speyeria cybele", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 6-9 cm", "habitat": "Moist meadows, forest clearings, prairies and roadsides rich in nectar flowers; larvae feed only on violets.", "tips": "Large orange-brown wings with black spots and chevrons above; underside of the hindwing is warm brown with bright silvery-white spots and a wide pale band.", "fact": "Females lay eggs in late summer near (not on) violets, and the tiny caterpillars hatch, then overwinter without feeding, waiting until spring when fresh violet leaves appear.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "isabella-tiger-moth", "name": "Isabella tiger moth (woolly bear)", "sci": "Pyrrharctia isabella", "cat": "insects", "sub": "butterflies-moths", "emoji": "🐛", "size": "Wingspan 4.5-6.5 cm; caterpillar to 5 cm", "habitat": "Fields, meadows, forest edges, gardens and roadsides; the caterpillar feeds on many low herbs including plantain, dandelion and grasses.", "tips": "Adult is a fuzzy yellow-orange to tan moth with faint dark specks; far better known as the 'woolly bear' caterpillar, black at both ends with a rusty-orange band in the middle.", "fact": "Folklore claims a wider orange band means a milder winter, but the band actually reflects the caterpillar's age; the woolly bear survives being frozen solid by producing a natural antifreeze.", "seasons": ["spring", "summer", "fall"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Woolly bear bristles are harmless but can cause a mild, brief itch in sensitive people if handled.", "region": "Province-wide", "angling": ""},
  {"id": "question-mark-butterfly", "name": "Question mark", "sci": "Polygonia interrogationis", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 5.5-7.5 cm", "habitat": "Woodland edges, parks, city gardens and wooded suburbs; larvae feed on elm, hackberry, nettle and hops.", "tips": "Larger than the Eastern comma with a small violet-tipped tail on each hindwing; the underside silver mark is a curved line plus a separate dot, forming a question mark.", "fact": "It has two seasonal forms: summer adults have mostly black hindwings, while the overwintering fall form shows more orange and stronger violet wing edges.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "silver-spotted-skipper", "name": "Silver-spotted skipper", "sci": "Epargyreus clarus", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 4.5-6.5 cm", "habitat": "Meadows, gardens, forest edges and roadsides; larvae feed on legumes such as black locust, hog-peanut and wisteria.", "tips": "Large brown skipper with a golden-orange band on the forewing and a bright silvery-white patch on the underside of each hindwing; flies fast with rapid, darting wingbeats.", "fact": "The caterpillar lives in a leaf shelter it sews shut with silk and can flick its frass (droppings) up to 40 body-lengths away, likely to keep predators from tracking it by scent.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "spring-azure", "name": "Spring azure", "sci": "Celastrina ladon", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 2-3 cm", "habitat": "Woodland edges, clearings, swamp borders and gardens; larvae feed on the flower buds of dogwoods, viburnums and other shrubs.", "tips": "Small; bright silvery-blue above with narrow black margins, and a chalky-white to pale grey underside with fine dark specks; among the earliest butterflies each spring.", "fact": "It is one of the first butterflies to appear in Ontario, sometimes flying while snow patches remain, and the closely related azures were long treated as a single confusing species.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "white-admiral", "name": "White admiral", "sci": "Limenitis arthemis", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 6.5-8.5 cm", "habitat": "Northern mixed and deciduous forests, clearings and dirt roads; larvae feed on birch, poplar, willow and cherry.", "tips": "Blackish wings crossed by a broad white band, with rows of blue and orange spots near the margins; often glides between sunny spots along forest trails.", "fact": "In southern Ontario it interbreeds with the tailless 'red-spotted purple' form of the same species, which drops the white band to mimic the distasteful pipevine swallowtail.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Central and northern Ontario (white form); south for intergrades", "angling": ""},
  {"id": "hummingbird-clearwing", "name": "Hummingbird clearwing", "sci": "Hemaris thysbe", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 4-5.5 cm", "habitat": "Gardens, meadows, forest edges and roadsides with abundant flowers; larvae feed on honeysuckle, hawthorn and viburnum.", "tips": "A plump day-flying sphinx moth with an olive-and-burgundy body and clear wing panels; hovers at flowers with a whirring blur, easily mistaken for a tiny hummingbird.", "fact": "Newly emerged adults have fully scaled wings, but the scales over the clear patches fall off during the moth's very first flight, leaving the see-through 'windows'.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "polyphemus-moth", "name": "Polyphemus moth", "sci": "Antheraea polyphemus", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 10-15 cm", "habitat": "Deciduous and mixed woods, orchards and shade-tree suburbs; larvae feed on oak, maple, birch and many other hardwoods.", "tips": "Large tan-to-reddish giant silkmoth with a big blue-and-yellow transparent eyespot on each hindwing and a smaller spot on each forewing; comes to lights at night.", "fact": "Named for the one-eyed giant Polyphemus of Greek myth, it flashes the large hindwing eyespots to startle predators; the non-feeding adult lives only about a week.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "autumn-meadowhawk", "name": "Autumn meadowhawk", "sci": "Sympetrum vicinum", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~3 cm", "habitat": "Ponds, marshes, ditches and slow water, often seen basking on warm surfaces late in the season.", "tips": "A small red dragonfly; mature males have a bright red abdomen and, unlike other meadowhawks, yellowish (not black) legs, the key field mark.", "fact": "It is one of the very last dragonflies on the wing in Ontario, sometimes flying into late October or November after frosts.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "blue-dasher", "name": "Blue dasher", "sci": "Pachydiplax longipennis", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~3-4 cm", "habitat": "Weedy, vegetated ponds, marshes and slow-moving water with abundant emergent plants.", "tips": "Males have a powdery pale-blue abdomen, a dark tip, brilliant blue-green eyes and a striped thorax; females and immatures show a dark abdomen with bold yellow dashes.", "fact": "On hot days it perches in an 'obelisk' pose, pointing its abdomen straight at the sun to shrink the surface exposed to heat.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "common-whitetail", "name": "Common whitetail", "sci": "Plathemis lydia", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~4.2-4.8 cm", "habitat": "Ponds, slow streams, ditches and muddy-bottomed wetlands, often in disturbed or sunny settings.", "tips": "Mature males have a stout, chalky-white pruinose abdomen and a single broad dark band across each wing; females are brown with a row of pale zigzag side-marks and three dark wing spots.", "fact": "Territorial males flash their bright white abdomen at rivals as a visual 'keep out' signal along the shoreline.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "eastern-pondhawk", "name": "Eastern pondhawk", "sci": "Erythemis simplicicollis", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~4 cm", "habitat": "Ponds, marshes and slow streams; frequently perches flat on the ground, docks or lily pads.", "tips": "Females and young males are bright grass-green with black-banded abdomens; mature males turn powdery blue but keep a green face, a useful clincher.", "fact": "A bold ambush predator, it readily catches and eats other dragonflies, including damselflies and even members of its own species.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "widow-skimmer", "name": "Widow skimmer", "sci": "Libellula luctuosa", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~4.5 cm", "habitat": "Still and slow water: ponds, marshes, lake edges and ditches with open, sunny perches.", "tips": "Broad dark brown-black patch at the base of each wing; mature males add a chalky white band beyond the dark base, while females and young males show only the brown bases with yellow side-stripes on the body.", "fact": "The name 'widow' comes from the dark wing patches, likened to a mourning shawl draped over the insect.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "calico-pennant", "name": "Calico pennant", "sci": "Celithemis elisa", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~2.5-3.5 cm", "habitat": "Vegetated pond and lake edges, marshes and boggy wetlands with grassy perches.", "tips": "Small pennant with amber and dark spots patterning the wings and a row of pale heart-shaped spots down the top of the abdomen, red in males and yellow in females.", "fact": "The neat line of heart-shaped marks along its back makes it one of the most easily recognized small dragonflies in the region.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "halloween-pennant", "name": "Halloween pennant", "sci": "Celithemis eponina", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~4 cm", "habitat": "Marshes, ponds and lake margins with tall grasses, sedges and open meadow nearby.", "tips": "Wings are broadly washed with orange-amber and crossed by dark brown bands, giving a stained-glass, butterfly-like look; it perches at the very tips of stems.", "fact": "Named for its orange-and-black colours, it flutters and sways on grass tips like a little flag or pennant in the breeze.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "bicoloured-striped-sweat-bee", "name": "Bicoloured striped sweat bee", "sci": "Agapostemon virescens", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "~10-12 mm", "habitat": "Gardens, meadows, prairies, roadsides and city parks; nests communally in burrows in bare or sparsely vegetated ground.", "tips": "Brilliant metallic green head and thorax; females have a boldly black-and-white striped abdomen, while males add a yellow-and-black banded one.", "fact": "In 2018 this dazzling native bee was named the official bee of the City of Toronto in recognition of its role as an urban pollinator.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Non-aggressive; may land on skin to drink sweat and can give a mild sting only if pressed or trapped against the body.", "region": "Southern and central Ontario, including cities such as Toronto", "angling": ""},
  {"id": "two-spotted-bumble-bee", "name": "Two-spotted bumble bee", "sci": "Bombus bimaculatus", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Queen ~2 cm, workers ~1-1.5 cm", "habitat": "Woodlands, forest edges, gardens and meadows; nests underground or in cavities such as old logs and abandoned burrows.", "tips": "Yellow thorax and yellow first abdominal segment, with a distinctive yellow 'W' or two-lobed spot on the otherwise black second segment.", "fact": "One of Ontario's earliest bumble bees, its queens emerge in early spring to pollinate blooms like spring beauty and Dutchman's breeches before most other bees.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Docile and unlikely to sting away from the nest, but like all bumble bees it can sting repeatedly in defence.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "eastern-cicada-killer", "name": "Eastern cicada killer", "sci": "Sphecius speciosus", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Females ~30-40 mm, males smaller", "habitat": "Sunny, well-drained sandy or bare soil in gardens, lawns, banks, trails and ballfields, often near trees where cicadas sing.", "tips": "Very large wasp with a rusty-red thorax, black abdomen marked with pale yellow bands, and amber-tinted wings; flies low over the ground at nest sites.", "fact": "A female hunts, stings and paralyzes an annual cicada, then flies the heavy prey back to her burrow as living food for a single larva.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Alarmingly large but non-aggressive; the territorial males that buzz people have no stinger, and females sting only if grabbed or stepped on.", "region": "Southern Ontario, especially the Carolinian zone with sandy soils", "angling": ""},
  {"id": "great-golden-digger-wasp", "name": "Great golden digger wasp", "sci": "Sphex ichneumoneus", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "~20-28 mm", "habitat": "Open sunny sites with light soil: gardens, prairies, roadsides and sandy banks; nests in self-dug ground burrows, frequently visiting flowers.", "tips": "Slim wasp with golden hairs on a black head and thorax, orange-red legs, and an abdomen that is orange at the base and black at the tip.", "fact": "The female provisions each burrow cell with paralyzed katydids or grasshoppers, inspecting the nest before dragging in prey in a fixed, instinctive routine.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "A solitary, non-aggressive wasp that focuses on hunting insects; it can sting but almost never does unless roughly handled.", "region": "Southern Ontario", "angling": ""},
  {"id": "yellow-banded-bumble-bee", "name": "Yellow-banded bumble bee", "sci": "Bombus terricola", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Queen ~1.7-2.1 cm, workers smaller", "habitat": "Meadows, farmland, forest edges, wetlands and northern clearings; nests underground, often in abandoned rodent burrows.", "tips": "Fuzzy black bee with yellow on the front of the thorax and yellow bands on the second and third abdominal segments, and a black head.", "fact": "Once one of the most common bumble bees in the region, it declined sharply in the 1990s and is now a species of Special Concern.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "uncommon", "status": "Special Concern", "atRisk": true, "caution": "A protected species of conservation concern; observe and photograph rather than collect. Can sting repeatedly if handled but is generally docile.", "region": "Across Ontario from the south to the boreal, but much reduced from its former range", "angling": ""},
  {"id": "american-carrion-beetle", "name": "American Carrion Beetle", "sci": "Necrophila americana", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~12-22 mm", "habitat": "Forests, fields and roadsides around carcasses, dung and other decaying matter.", "tips": "Flattened black beetle with a large pale yellow pronotum bearing a dark central spot; often seen crawling over or flying to fresh carrion.", "fact": "Adults and larvae recycle nutrients by feeding on carrion and on the fly maggots competing for it, and they ferry hitchhiking mites from one carcass to the next.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Native", "atRisk": false, "caution": "May give off a foul odour when handled.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "goldenrod-soldier-beetle", "name": "Goldenrod Soldier Beetle", "sci": "Chauliognathus pensylvanicus", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~9-13 mm", "habitat": "Meadows, gardens and roadsides, especially on goldenrod and other late-summer flowers.", "tips": "Elongate and soft-bodied; orange-yellow with a large black spot on each wing case and one on the pronotum. The flexible leathery wing covers give it the alternate name 'Pennsylvania leatherwing'.", "fact": "Both stages are beneficial: adults pollinate flowers while feeding on pollen and nectar, and the larvae prey on the eggs and larvae of insect pests.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "six-spotted-tiger-beetle", "name": "Six-spotted Tiger Beetle", "sci": "Cicindela sexguttata", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~10-14 mm", "habitat": "Sunny paths, trail edges and clearings in deciduous and mixed woodland.", "tips": "Brilliant iridescent green (sometimes blue-green) with long legs, large bulging eyes and sickle-shaped mandibles; usually a few tiny white spots along the wing-case margins (often six, but variable or absent).", "fact": "One of the fastest running insects for its size; it sprints so quickly after prey that its vision blurs and it must pause to relocate the target.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Harmless to people; the large mandibles may deliver a slight pinch if the beetle is handled.", "region": "Southern and central Ontario, widespread", "angling": ""},
  {"id": "whirligig-beetle", "name": "Whirligig Beetle", "sci": "Dineutus assimilis", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~9-15 mm", "habitat": "Surface of ponds, lakes and slow-moving streams, often in gregarious clusters.", "tips": "Small, shiny blue-black and oval, seen swimming in rapid gyrating circles on the water surface; each compound eye is split into an upper and lower half.", "fact": "Its divided eyes let it watch above and below the waterline at the same time, scanning for prey and predators simultaneously.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Native", "atRisk": false, "caution": "Releases a fruity, apple-scented defensive fluid when handled; harmless.", "region": "Ponds and lakes across Ontario", "angling": ""},
  {"id": "eastern-eyed-click-beetle", "name": "Eastern Eyed Click Beetle", "sci": "Alaus oculatus", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~25-45 mm", "habitat": "Deciduous and mixed forests, on and around decaying logs and dead wood.", "tips": "Large and elongate, black mottled with fine white and grey speckling; unmistakable for the two big black false eyespots ringed in white on the pronotum (behind the head).", "fact": "When flipped onto its back it snaps a spine-and-groove hinge on its underside to launch itself into the air with a loud audible click, flipping upright.", "seasons": ["spring", "summer"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario deciduous forests", "angling": ""},
  {"id": "reddish-brown-stag-beetle", "name": "Reddish-brown Stag Beetle", "sci": "Lucanus capreolus", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~22-35 mm (males larger, including mandibles)", "habitat": "Deciduous and mixed woodlands near rotting logs, stumps and buried decaying wood.", "tips": "Shiny reddish-brown to mahogany; males bear large antler-like mandibles. The bicoloured legs, with a distinct yellowish-orange patch on the femora, separate it from the darker giant stag beetle.", "fact": "The grub-like larvae feed inside decaying wood for one to two years before pupating and emerging as adults.", "seasons": ["summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Males can give a firm pinch with their mandibles if picked up, but it is harmless.", "region": "Southern Ontario", "angling": ""},
  {"id": "american-dog-tick", "name": "American dog tick", "sci": "Dermacentor variabilis", "cat": "insects", "sub": "other-insects", "emoji": "🕷️", "size": "Unfed ~3-5 mm; engorged up to ~15 mm", "habitat": "Grassy meadows, trail edges, old fields and scrubby areas, often along paths used by people and dogs.", "tips": "An arachnid, not an insect: eight legs, no wings. Larger and more rounded than the blacklegged tick, brown with distinctive silvery-white mottled markings on the shield (males patterned overall, females with a pale shield behind the head).", "fact": "Unlike the blacklegged (deer) tick, the American dog tick does NOT transmit Lyme disease, but it can carry the agents of Rocky Mountain spotted fever and tularemia (both rare in Ontario).", "seasons": ["spring", "summer"], "activity": "varies", "seen": "common", "status": "Native", "atRisk": false, "caution": "Bites people and pets and can rarely transmit Rocky Mountain spotted fever or tularemia. Do tick checks after being outdoors, remove any attached tick promptly with fine-tipped tweezers, and watch for fever or rash.", "region": "Southern and eastern Ontario (grassy and open habitats)", "angling": ""},
  {"id": "boxelder-bug", "name": "Boxelder bug", "sci": "Boisea trivittata", "cat": "insects", "sub": "other-insects", "emoji": "🪲", "size": "~11-14 mm", "habitat": "On and around boxelder, maple and ash trees; gathers on warm sunny walls, fences and foundations in autumn.", "tips": "A flattened, dark brownish-black true bug marked with three thin red-orange lines on the thorax and red veins outlining the wings; nymphs are bright red. Frequently seen in large aggregations.", "fact": "In autumn these bugs mass on warm, sun-lit walls and squeeze into homes to overwinter; they are a harmless nuisance that neither bites nor damages the house, though crushing them can leave a stain.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "carolina-grasshopper", "name": "Carolina grasshopper", "sci": "Dissosteira carolina", "cat": "insects", "sub": "other-insects", "emoji": "🦗", "size": "Body ~3-5 cm", "habitat": "Open, dry, disturbed ground: gravel lots, roadsides, trail edges, railway cuttings, weedy fields and sandy lakeshores.", "tips": "A large grey-brown band-winged grasshopper superbly camouflaged on bare soil until it flushes, when it flashes broad black hindwings edged with a pale creamy-yellow border. Its low fluttering flight can be mistaken for a mourning cloak butterfly; the instant it lands it snaps the wings shut and vanishes against the ground.", "fact": "The bold black-and-cream hindwings, hidden at rest and revealed only in flight, help startle predators, and males sometimes hover in place to display them during courtship.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario (open, disturbed ground)", "angling": ""},
  {"id": "fall-field-cricket", "name": "Fall field cricket", "sci": "Gryllus pennsylvanicus", "cat": "insects", "sub": "other-insects", "emoji": "🦗", "size": "Body ~15-25 mm", "habitat": "Fields, lawns, roadsides, gardens and under logs and stones; often enters buildings in autumn.", "tips": "A robust, shiny black cricket with long antennae, powerful jumping hind legs and, on females, a long needle-like ovipositor at the rear. Males chirp a mellow, repeated 'chirp-chirp' by rubbing their wings together.", "fact": "This species overwinters as eggs and matures in late summer, so its cheerful chirping through cool autumn nights is a classic sound of fall in Ontario; only the males sing.", "seasons": ["summer", "fall"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "large-milkweed-bug", "name": "Large milkweed bug", "sci": "Oncopeltus fasciatus", "cat": "insects", "sub": "other-insects", "emoji": "🪲", "size": "~10-18 mm", "habitat": "Milkweed patches in meadows, old fields, ditches and gardens where seed pods develop.", "tips": "An elongate true bug boldly patterned in orange and black, with a broad black band across the middle of the back separating two orange zones (unlike the small milkweed bug, which shows a black-bordered red 'X'). Often clusters in groups on milkweed seed pods.", "fact": "Its bright orange-and-black warning colours advertise that toxins (cardenolides) taken up from milkweed seeds make it distasteful to birds and other predators.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario (wherever milkweed grows)", "angling": ""},
  {"id": "snowy-tree-cricket", "name": "Snowy tree cricket", "sci": "Oecanthus fultoni", "cat": "insects", "sub": "other-insects", "emoji": "🦗", "size": "Body ~13-15 mm", "habitat": "Shrubs, hedgerows, tall weeds and the edges of deciduous woods and gardens.", "tips": "A delicate, pale whitish-green cricket with long antennae and flat, translucent wings held over the back; far more often heard than seen. Its call is a soft, steady, rhythmic chirping, distinct from the harsher trill of ground crickets.", "fact": "It is the 'thermometer cricket': count its chirps over 13 seconds and add 40 to get the air temperature in degrees Fahrenheit, a relationship known as Dolbear's law.", "seasons": ["summer", "fall"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "giant-water-bug", "name": "Giant water bug", "sci": "Lethocerus americanus", "cat": "insects", "sub": "other-insects", "emoji": "🪳", "size": "~4-6 cm", "habitat": "Weedy ponds, marshes, ditches and quiet lake margins; adults fly to lights at night.", "tips": "A very large, flat, oval brown bug with grasping, raptorial front legs and short breathing appendages at the tail tip. One of the biggest true bugs in Ontario; often mistaken for a beetle.", "fact": "Nicknamed the 'toe-biter' for its painful defensive jab and the 'electric light bug' for its habit of flying to lights, it is a fierce ambush predator that seizes tadpoles, insects and even small fish and injects digestive saliva.", "seasons": ["spring", "summer", "fall"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Can deliver a sharp, painful defensive bite if handled; not venomous or dangerous, but do not pick it up bare-handed.", "region": "Province-wide (ponds and wetlands)", "angling": ""},
  {"id": "northern-walkingstick", "name": "Northern walkingstick", "sci": "Diapheromera femorata", "cat": "insects", "sub": "other-insects", "emoji": "🌿", "size": "Female ~7.5-9.5 cm, male ~5-7 cm", "habitat": "Deciduous and mixed woodlands and their edges, on the foliage of oak, hazel, cherry and other hardwoods.", "tips": "An extremely slender, wingless, twig-like insect with very long thin legs and antennae; brown or greenish and easily overlooked as a bit of stem. Moves slowly and sways gently to mimic a branch in the breeze.", "fact": "It is Ontario's longest insect, a master of camouflage that eats leaves at night, and young nymphs can regenerate a lost leg at the next moult.", "seasons": ["summer", "fall"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario (Carolinian and deciduous forests)", "angling": ""},
  {"id": "black-swallowtail", "name": "Black swallowtail", "sci": "Papilio polyxenes", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 7-9 cm", "habitat": "Open fields, gardens and roadsides; larvae feed on carrot-family plants including dill, parsley and Queen Anne's lace.", "tips": "Black wings with two rows of yellow spots and blue on the hindwing; females show more blue, males more yellow.", "fact": "The green-and-black banded caterpillar rears an orange forked 'osmeterium' behind its head to deter predators with a foul smell.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "cabbage-white", "name": "Cabbage white", "sci": "Pieris rapae", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 4-6 cm", "habitat": "Gardens, farm fields, vacant lots and virtually any open, disturbed ground.", "tips": "Small white butterfly with black wingtips; females have two black forewing spots, males one.", "fact": "Introduced from Europe in the 1860s, it is now one of the most abundant butterflies in Ontario and a familiar garden pest as a green 'cabbage worm'.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Introduced", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "eastern-tiger-swallowtail", "name": "Eastern tiger swallowtail", "sci": "Papilio glaucus", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 8-14 cm", "habitat": "Deciduous woodland edges, riverbanks, gardens and roadsides.", "tips": "Large yellow butterfly with four black 'tiger' stripes on each forewing and tailed hindwings; some southern females are all-black mimics.", "fact": "Males often gather at damp ground or puddles to 'puddle' for minerals, sometimes in showy clusters.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "monarch", "name": "Monarch", "sci": "Danaus plexippus", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 9-10 cm", "habitat": "Meadows, roadsides, gardens and old fields with milkweed and abundant nectar flowers.", "tips": "Deep orange wings with heavy black veins and a black, white-spotted border; look for it nectaring or gliding low over milkweed.", "fact": "Ontario monarchs migrate up to 4,000 km to overwinter in the fir forests of central Mexico, a journey spanning several generations.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Special concern", "atRisk": true, "caution": "", "region": "Province-wide (breeds province-wide, migrates to Mexico)", "angling": ""},
  {"id": "mourning-cloak", "name": "Mourning cloak", "sci": "Nymphalis antiopa", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 6-10 cm", "habitat": "Woodlands, forest edges and clearings; often near sap flows and rotting fruit rather than flowers.", "tips": "Deep maroon-brown wings edged with a cream-yellow border and a row of blue spots; underside looks like dead bark.", "fact": "Adults overwinter under bark and are often the first butterfly seen in Ontario, flying on warm days before the snow is gone.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "painted-lady", "name": "Painted lady", "sci": "Vanessa cardui", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 5-7 cm", "habitat": "Open flowery habitats, gardens, fields and roadsides.", "tips": "Orange, black and white patterned upperwings; underside has a marbled pattern with four small eyespots.", "fact": "One of the world's most widespread butterflies; it cannot survive Ontario winters and recolonizes each year from the south, sometimes in huge irruptions.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide (migratory, numbers vary yearly)", "angling": ""},
  {"id": "red-admiral", "name": "Red admiral", "sci": "Vanessa atalanta", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 4.5-6 cm", "habitat": "Woodland edges, gardens, parks and moist clearings; larvae feed on nettles.", "tips": "Black wings crossed by bright orange-red bands with white spots near the tips; often lands on tree trunks and people.", "fact": "A strong, territorial flier that migrates north each spring; males patrol sunlit spots and dart at passing intruders.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide (migratory)", "angling": ""},
  {"id": "spongy-moth", "name": "Spongy moth", "sci": "Lymantria dispar", "cat": "insects", "sub": "butterflies-moths", "emoji": "🐛", "size": "Wingspan 3-6 cm", "habitat": "Hardwood forests, especially oak; also urban and suburban trees.", "tips": "Caterpillars have five pairs of blue then six pairs of red raised spots down the back; buff females are flightless, brown males fly in a zigzag by day.", "fact": "An invasive defoliator (formerly called gypsy moth) whose outbreaks can strip entire oak stands bare in a single spring.", "seasons": ["spring", "summer"], "activity": "varies", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Invasive forest defoliator. Caterpillar hairs can cause an itchy skin rash in sensitive people. Do not move egg masses on firewood, vehicles or outdoor gear.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "viceroy", "name": "Viceroy", "sci": "Limenitis archippus", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 6.5-8.5 cm", "habitat": "Wet meadows, marsh edges, lakeshores and ditches with willows and poplars.", "tips": "Orange-and-black like a monarch but smaller, with a distinctive black line crossing the hindwing veins; flies with quick shallow flaps and flat glides.", "fact": "Long taught as a harmless mimic of the toxic monarch, the viceroy is itself distasteful, so the two form a mutual (Mullerian) mimicry pair that reinforces the warning colours.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "cecropia-moth", "name": "Cecropia moth", "sci": "Hyalophora cecropia", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 13-16 cm", "habitat": "Woodland edges, orchards and suburban yards with maples, cherries and other hardwoods.", "tips": "North America's largest native moth; reddish-brown wings with crescent-shaped white-and-red bands and a feathery-antennaed body.", "fact": "Like other giant silkmoths the adult does not eat; males detect a female's pheromone from over a kilometre away using enormous feathery antennae.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "giant-swallowtail", "name": "Giant swallowtail", "sci": "Papilio cresphontes", "cat": "insects", "sub": "butterflies-moths", "emoji": "🦋", "size": "Wingspan 10-16 cm", "habitat": "Carolinian woodland edges, gardens and citrus-family hosts such as prickly-ash and hop-tree.", "tips": "Canada's largest butterfly; dark wings crossed by a broad diagonal band of yellow spots, yellow underside.", "fact": "Its caterpillar mimics a fresh bird dropping, an effective disguise that lets it feed in plain sight.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario (Carolinian zone, expanding north)", "angling": ""},
  {"id": "luna-moth", "name": "Luna moth", "sci": "Actias luna", "cat": "insects", "sub": "butterflies-moths", "emoji": "🌙", "size": "Wingspan 8-11 cm", "habitat": "Deciduous forests with birch, walnut and hickory; adults come to lights at night.", "tips": "Unmistakable pale lime-green giant silkmoth with long twisted hindwing tails and small eyespots.", "fact": "Adults have no functional mouthparts and never feed, living only about a week solely to mate; the trailing tails confuse the sonar of hunting bats.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "common-green-darner", "name": "Common green darner", "sci": "Anax junius", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body 7-8 cm", "habitat": "Ponds, marshes, slow streams and lakeshores; often hunts far from water over fields.", "tips": "Large dragonfly with a bright green thorax and a blue (male) or purplish (female) abdomen; a bull's-eye mark sits on the forehead.", "fact": "One of the few migratory dragonflies in Ontario, with generations moving north in spring and south in fall much like birds.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "ebony-jewelwing", "name": "Ebony jewelwing", "sci": "Calopteryx maculata", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body 4-5 cm", "habitat": "Shaded, slow forest streams and creeks with overhanging vegetation.", "tips": "A broad-winged damselfly with entirely black wings and a metallic emerald-green (male) or brown-green (female) body; females show a white wing spot.", "fact": "It flutters weakly like a butterfly and often perches with wings folded, unlike most damselflies.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "twelve-spotted-skimmer", "name": "Twelve-spotted skimmer", "sci": "Libellula pulchella", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body ~5 cm", "habitat": "Marshes, ponds and slow-moving water with open, sunny perches.", "tips": "Each wing has three dark brown spots (twelve total); mature males add white patches between them, creating a bold checkerboard.", "fact": "Males are strongly territorial, patrolling a stretch of shoreline and perching conspicuously to chase off rivals.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "dragonhunter", "name": "Dragonhunter", "sci": "Hagenius brevistylus", "cat": "insects", "sub": "dragonflies", "emoji": "🐉", "size": "Body 7.5-9 cm", "habitat": "Clean rivers and forest-lined streams; hunts along shorelines and clearings.", "tips": "A huge black-and-yellow clubtail that flies with its long abdomen curled downward; the largest clubtail in the region.", "fact": "True to its name it preys on other large insects including butterflies and even other dragonflies such as darners.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "bald-faced-hornet", "name": "Bald-faced hornet", "sci": "Dolichovespula maculata", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Workers ~15-20 mm", "habitat": "Forest edges, gardens and yards; builds large grey paper nests in trees, shrubs and on buildings.", "tips": "Stout black wasp with an ivory-white face and white markings at the tail end; the football-shaped aerial nest is a giveaway.", "fact": "Actually a large yellowjacket rather than a true hornet, its papery nest can house several hundred workers by late summer.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Aggressively defends its nest and can sting repeatedly, spraying venom that guides more attackers. Stings are painful and can trigger severe allergic reactions.", "region": "Province-wide", "angling": ""},
  {"id": "common-eastern-bumble-bee", "name": "Common eastern bumble bee", "sci": "Bombus impatiens", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Queen ~2 cm, workers smaller", "habitat": "Gardens, meadows, farmland and cities; nests underground or in cavities.", "tips": "Robust, very fuzzy black bee with a single yellow band on the front of the abdomen and a yellow thorax.", "fact": "Ontario's most abundant bumble bee, it 'buzz-pollinates' by vibrating flowers to shake loose pollen that honey bees cannot reach.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Can sting, and unlike honey bees can sting repeatedly, but is generally docile and only defends the nest.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "eastern-carpenter-bee", "name": "Eastern carpenter bee", "sci": "Xylocopa virginica", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "~2-2.5 cm", "habitat": "Gardens, farmland and forest edges; excavates nest tunnels in bare, weathered wood such as fence rails, decks and eaves.", "tips": "Large bumble-bee-sized bee with a shiny, hairless black abdomen (bumble bees are fuzzy all over); males have a pale yellow face and hover at nest sites.", "fact": "Females bore nearly perfectly round tunnels into wood to raise their young, but they chew and discard the wood rather than eat it.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "The large hovering males cannot sting; females have a stinger but are docile and rarely sting unless handled.", "region": "Southern Ontario", "angling": ""},
  {"id": "eastern-yellowjacket", "name": "Eastern yellowjacket", "sci": "Vespula maculifrons", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "~12-16 mm", "habitat": "Fields, lawns, parks and picnic areas; nests underground or in wall voids.", "tips": "Short, stocky wasp with a shiny (not fuzzy) black-and-yellow banded abdomen; the common 'meat bee' at late-summer barbecues.", "fact": "Colonies grow all summer and turn aggressive and scavenging for sugars and protein by fall, which is when most stings occur.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Very aggressive, especially in late summer; stings repeatedly and defends hidden ground nests fiercely. Risk of anaphylaxis in sensitive people.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "honey-bee", "name": "Honey bee", "sci": "Apis mellifera", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Worker ~12-15 mm", "habitat": "Gardens, farmland, orchards and meadows; nests in managed hives and occasionally in hollow trees.", "tips": "Slim golden-brown bee with fuzzy thorax and dark abdominal bands; carries pollen in bright baskets on the hind legs.", "fact": "Introduced from Europe for honey and pollination, a single colony can hold tens of thousands of workers led by one queen.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Introduced", "atRisk": false, "caution": "Stings when handled or when the colony is threatened, leaving a barbed stinger. Venom can cause a severe allergic reaction (anaphylaxis) in sensitive people.", "region": "Province-wide (managed and feral)", "angling": ""},
  {"id": "paper-wasp", "name": "Northern paper wasp", "sci": "Polistes fuscatus", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "~15-20 mm", "habitat": "Gardens, eaves, sheds and porches; builds open, umbrella-shaped paper combs.", "tips": "Slender, long-legged brownish wasp with thin yellow markings; hind legs dangle in flight.", "fact": "Individuals recognize each other by unique facial markings, an unusual ability that helps maintain a pecking order in the nest.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Stings when the nest is approached; the sting is painful and can cause allergic reactions.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "rusty-patched-bumble-bee", "name": "Rusty-patched bumble bee", "sci": "Bombus affinis", "cat": "insects", "sub": "bees-wasps", "emoji": "🐝", "size": "Workers ~1-1.5 cm, queen ~2 cm", "habitat": "Formerly gardens, savannahs and open woodlands with a long succession of flowers.", "tips": "Workers and males show a distinctive rusty-brown patch centred on an otherwise yellow second abdominal segment.", "fact": "Once common, it has crashed by an estimated 90% and is now endangered and possibly extirpated from Ontario; any sighting should be reported.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "rare", "status": "Endangered", "atRisk": true, "caution": "Endangered and legally protected in Ontario. Do not capture or disturb; can sting if handled.", "region": "Historically southern Ontario; now extremely rare or possibly extirpated", "angling": ""},
  {"id": "emerald-ash-borer", "name": "Emerald ash borer", "sci": "Agrilus planipennis", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "8.5-14 mm", "habitat": "Ash trees in forests, woodlots and urban streets.", "tips": "Narrow, elongated beetle with brilliant metallic emerald-green wing cases; look for D-shaped exit holes and S-shaped larval galleries under bark.", "fact": "An invasive Asian beetle that has killed tens of millions of ash trees across Ontario since its 2002 discovery near Windsor.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Invasive forest pest that is lethal to native ash trees. Do not move firewood, which spreads the larvae to new areas.", "region": "Southern and central Ontario (spreading)", "angling": ""},
  {"id": "common-eastern-firefly", "name": "Firefly (big dipper)", "sci": "Photinus pyralis", "cat": "insects", "sub": "beetles", "emoji": "✨", "size": "~10-14 mm", "habitat": "Moist meadows, marsh edges, forest borders and lawns near water.", "tips": "Soft-bodied dark beetle with a pink-and-black shield over the head and a pale-edged wing case; best identified at night by its glow.", "fact": "Fireflies are beetles, not flies; males produce a rising J-shaped flash to which females reply, each species using its own coded pattern.", "seasons": ["summer"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  {"id": "japanese-beetle", "name": "Japanese beetle", "sci": "Popillia japonica", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~9-11 mm", "habitat": "Gardens, lawns, farmland and woodland edges; larvae ('white grubs') feed on turf roots.", "tips": "Shiny metallic-green body with coppery-bronze wing cases and five small tufts of white hairs along each side of the abdomen.", "fact": "An invasive beetle now established across southern Ontario, it skeletonizes the leaves of roses, grapes, lindens and hundreds of other plants, often feeding in large groups.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Invasive garden and turf pest that damages many plants, with larvae harming lawns. Avoid moving soil or infested plant material to new areas.", "region": "Southern and central Ontario (spreading)", "angling": ""},
  {"id": "june-beetle", "name": "June beetle", "sci": "Phyllophaga spp.", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "~12-25 mm", "habitat": "Lawns, pastures and woodland edges; larvae ('white grubs') live in soil feeding on roots.", "tips": "Heavy-bodied glossy reddish-brown beetle that flies clumsily and buzzes loudly around lights on early summer nights.", "fact": "Also called June bugs, the adults emerge in late spring and are strongly drawn to porch lights, often crashing into windows and walls.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "asian-lady-beetle", "name": "Multicoloured Asian lady beetle", "sci": "Harmonia axyridis", "cat": "insects", "sub": "beetles", "emoji": "🐞", "size": "5.5-8.5 mm", "habitat": "Gardens, crops and forests in summer; clusters on and inside buildings in autumn.", "tips": "Highly variable orange to red with 0-19 spots; look for the black 'M' or 'W' mark on the whitish plate behind the head.", "fact": "Introduced for pest control, it now outcompetes native ladybugs and famously swarms warm south-facing walls to overwinter indoors.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Introduced", "atRisk": false, "caution": "Invasive; displaces native ladybugs. Can deliver a small nip and, when disturbed, oozes a foul-smelling, staining yellow reflex fluid; large indoor aggregations can trigger allergies.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "seven-spotted-lady-beetle", "name": "Seven-spotted lady beetle", "sci": "Coccinella septempunctata", "cat": "insects", "sub": "beetles", "emoji": "🐞", "size": "6-8 mm", "habitat": "Gardens, crops, meadows and roadsides wherever aphids are plentiful.", "tips": "Domed red-orange beetle with exactly seven black spots and small white patches beside the head.", "fact": "Introduced from Europe as an aphid control, both adults and larvae are voracious aphid predators.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Introduced", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "dogbane-beetle", "name": "Dogbane beetle", "sci": "Chrysochus auratus", "cat": "insects", "sub": "beetles", "emoji": "🪲", "size": "8-11 mm", "habitat": "Meadows, ditches and field edges wherever dogbane and milkweed grow.", "tips": "Small, oval leaf beetle that gleams iridescent green, gold, copper and blue depending on the angle of light.", "fact": "Its dazzling metallic colour comes from microscopic layers in the shell that bend light, and it feeds almost exclusively on toxic dogbane.", "seasons": ["summer"], "activity": "diurnal", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "black-fly", "name": "Black fly", "sci": "Simulium spp.", "cat": "insects", "sub": "other-insects", "emoji": "🦟", "size": "1-5 mm", "habitat": "Near clean running water where larvae develop; swarms drift into forests, trails and yards.", "tips": "Tiny stout, hump-backed dark fly with broad clear wings; a bite often bleeds and swells more than a mosquito bite.", "fact": "Larvae anchor to rocks in fast, oxygen-rich streams, so heavy black fly seasons are a sign of clean flowing water nearby.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Females bite by day, often around the head and ankles; bites are painful, itchy and can cause swelling, welts or allergic reactions.", "region": "Province-wide (worst in the north and near running water)", "angling": ""},
  {"id": "green-lacewing", "name": "Common green lacewing", "sci": "Chrysoperla carnea", "cat": "insects", "sub": "other-insects", "emoji": "🦟", "size": "~1-1.5 cm", "habitat": "Gardens, fields and woodland edges; adults often come to lights at night.", "tips": "Delicate pale-green insect with golden eyes and large clear, finely veined wings held roof-like over the body.", "fact": "Its spiny larva, nicknamed the 'aphid lion', is a fierce predator that devours aphids, mites and other soft pests by the hundreds.", "seasons": ["spring", "summer", "fall"], "activity": "nocturnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "water-strider", "name": "Common water strider", "sci": "Aquarius remigis", "cat": "insects", "sub": "other-insects", "emoji": "🪳", "size": "Body ~1-1.5 cm", "habitat": "Calm surfaces of ponds, slow streams, pools and quiet lake edges.", "tips": "Slim dark bug that skates on the water surface on long splayed legs, casting dimpled shadows on the bottom.", "fact": "Dense water-repellent leg hairs let it stand on surface tension without breaking through, and it detects struggling prey by ripples.", "seasons": ["spring", "summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Province-wide", "angling": ""},
  {"id": "deer-fly", "name": "Deer fly", "sci": "Chrysops spp.", "cat": "insects", "sub": "other-insects", "emoji": "🦟", "size": "~1 cm", "habitat": "Open trails, marsh and forest edges and lakeshores on warm, still, sunny days.", "tips": "Broad flat fly with patterned banded wings and bright green or golden eyes; circles the head persistently before landing.", "fact": "The female's scissor-like mouthparts slice the skin to lap blood, which is why the bite is sharply painful and hard to ignore.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "Females deliver a sharp, cutting bite and pursue relentlessly; bites can swell, become infected or provoke allergic reactions.", "region": "Province-wide", "angling": ""},
  {"id": "dog-day-cicada", "name": "Dog-day cicada", "sci": "Neotibicen canicularis", "cat": "insects", "sub": "other-insects", "emoji": "🦗", "size": "Body ~2.5-3.5 cm", "habitat": "Forests, woodlots, parks and leafy neighbourhoods with mature trees.", "tips": "Stout green, black and white insect with clear, green-veined wings held tent-like over the body; far more often heard than seen high in the canopy.", "fact": "Its loud, whining buzz is the classic sound of the hot 'dog days' of late summer in Ontario; males sing with drum-like organs called tymbals, and the nymphs spend years underground feeding on root sap.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "common", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "northern-house-mosquito", "name": "Mosquito", "sci": "Culex pipiens", "cat": "insects", "sub": "other-insects", "emoji": "🦟", "size": "3-6 mm", "habitat": "Anywhere near standing water; larvae thrive in ditches, containers, rain barrels and stagnant pools.", "tips": "Slender long-legged fly with a piercing proboscis; rests with the body angled and whines audibly in flight.", "fact": "Only females bite, needing a blood meal to develop eggs; this species is the main Ontario carrier of West Nile virus.", "seasons": ["spring", "summer", "fall"], "activity": "crepuscular", "seen": "common", "status": "Native", "atRisk": false, "caution": "Bites and can transmit West Nile virus (and rarely eastern equine encephalitis) in Ontario. Use repellent and drain standing water around the home.", "region": "Province-wide", "angling": ""},
  {"id": "blacklegged-tick", "name": "Blacklegged (deer) tick", "sci": "Ixodes scapularis", "cat": "insects", "sub": "other-insects", "emoji": "🕷️", "size": "Adult ~3-5 mm (larger when engorged)", "habitat": "Leaf litter, tall grass and brushy edges of woods, especially in southern and eastern Ontario.", "tips": "An arachnid, not an insect: eight legs, no wings; reddish-orange body with a dark shield and dark legs, no white markings (unlike the dog tick, which doesn't spread Lyme).", "fact": "It waits at the tips of vegetation and latches onto passing hosts; nymphs are poppy-seed sized and cause most human Lyme cases.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Primary vector of Lyme disease (and anaplasmosis and other pathogens) in Ontario. Do tick checks after being outdoors, remove any attached tick promptly with fine tweezers, and seek medical care if a bull's-eye rash or flu-like illness develops.", "region": "Southern and eastern Ontario, expanding (established risk areas)", "angling": ""},
  {"id": "european-mantis", "name": "European mantis", "sci": "Mantis religiosa", "cat": "insects", "sub": "other-insects", "emoji": "🦗", "size": "5-7.5 cm", "habitat": "Meadows, gardens, old fields and hedgerows with tall grasses and flowers.", "tips": "Slender green or brown insect with a triangular swivelling head and folded, spined 'praying' forelegs; a black-ringed spot marks the inner front leg.", "fact": "Introduced to North America around 1900, it is the mantis usually seen in Ontario and hunts by ambush, seizing prey with lightning-fast forelegs.", "seasons": ["summer", "fall"], "activity": "diurnal", "seen": "uncommon", "status": "Introduced", "atRisk": false, "caution": "", "region": "Southern Ontario", "angling": ""},
  // ---- Fungi (49) ----
  {"id": "fairy-ring-mushroom", "name": "Fairy Ring Mushroom", "sci": "Marasmius oreades", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Cap 2-5 cm wide; tough thin stem 3-7 cm tall", "habitat": "Lawns, pastures, and grassy areas, typically growing in arcs or complete rings.", "tips": "Tan to buff bell-shaped cap with a broad central bump (umbo); widely spaced pale gills that do not run down the stem; tough, pliable, wiry stem; white spore print; dried caps revive and continue shedding spores after rewetting.", "fact": "Its rings can expand outward through a lawn for decades as the underground mycelium grows, giving rise to the folklore of 'fairy rings.'", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Deadly look-alikes share the same lawns: fool's funnel (Clitocybe dealbata / C. rivulosa) and other small white Clitocybe contain muscarine and can kill, they have crowded gills that run down the stem and lack an umbo. Poisonous little brown mushrooms also grow in grass. Never eat any wild mushroom unless an expert confirms it.", "region": "Lawns, parks, and pastures across southern and central Ontario", "angling": ""},
  {"id": "meadow-mushroom", "name": "Meadow Mushroom", "sci": "Agaricus campestris", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Cap 5-10 cm wide; stem 3-7 cm tall", "habitat": "Grassy meadows, pastures, lawns, and fields (not in woods), often appearing in numbers after late-summer rains.", "tips": "White silky cap, gills bright pink when young darkening to chocolate-brown, with a dark brown spore print and a thin ring on the stem; flesh stays white or bruises only faintly pink; there is no cup at the base and no yellow staining.", "fact": "It is a wild relative of the cultivated white button mushroom (Agaricus bisporus) found in grocery stores.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Deadly look-alikes: young destroying angels (Amanita bisporigera, A. virosa) have WHITE gills, a WHITE spore print, and a cup (volva) at the stem base, always check gill colour and dig up the whole base. The toxic yellow-stainer (Agaricus xanthodermus) bruises bright chrome-yellow at the stem base and smells of phenol or ink. Never eat any wild mushroom unless an expert confirms it.", "region": "Fields, pastures, and lawns of southern and central Ontario", "angling": ""},
  {"id": "pear-shaped-puffball", "name": "Pear-shaped Puffball", "sci": "Apioperdon pyriforme", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Fruitbody 1.5-4.5 cm wide, pear- to top-shaped", "habitat": "Clustered on decaying logs, stumps, and buried wood, frequently in dense troops.", "tips": "The only common puffball that fruits on wood; pear-shaped bodies attached to the log by white cords (rhizomorphs), with a smooth to finely warted surface and pure white, uniform interior when edible; mature bodies turn olive-brown and puff spores from a top pore.", "fact": "Unlike other puffballs it grows directly on rotting wood, often in showy clusters of dozens on a single log.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Slice every puffball top to bottom before eating: the flesh must be pure, homogeneous white. Any outline of a developing cap, gills, or stem means it is a deadly Amanita 'egg' (destroying angel). Avoid earthballs (Scleroderma), which have firm purple-black interiors and are toxic. Never eat any wild mushroom unless an expert confirms it.", "region": "Forests and woodlots across southern, central, and northern Ontario", "angling": ""},
  {"id": "winter-chanterelle", "name": "Winter Chanterelle (Yellowfoot)", "sci": "Craterellus tubaeformis", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Cap 1-6 cm wide; slender hollow stem 3-8 cm tall", "habitat": "Damp, mossy coniferous and mixed forests, often in troops on rotting wood, needle duff, and moss beds.", "tips": "Small brown to greyish funnel-shaped cap over a hollow yellow to yellow-brown stem; underside has shallow, blunt, forking false ridges (not true knife-edged gills) that run down the stem.", "fact": "One of the last edibles of the year, it often fruits well into late fall after the first frosts, earning the name 'winter' chanterelle.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Look-alikes include the toxic false chanterelle (Hygrophoropsis aurantiaca, which has crowded, forked true gills) and the poisonous jack-o'-lantern (Omphalotus illudens, which grows in clusters on wood with true, blade-like gills). Never eat any wild mushroom unless an expert confirms it.", "region": "Boreal and mixed forests across northern, central, and cottage-country Ontario", "angling": ""},
  {"id": "aborted-entoloma", "name": "Aborted Entoloma", "sci": "Entoloma abortivum", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Aborted lumps 2-10 cm across; normal form cap 4-10 cm wide", "habitat": "On soil and rotting wood in hardwood and mixed forests, frequently near honey mushrooms (Armillaria).", "tips": "The commonly eaten 'aborted' form is a lumpy, off-white to greyish puffy mass with pinkish, marbled flesh inside; the normal form is a grey-capped mushroom with salmon-pink gills that run down the stem and a distinctly pink spore print.", "fact": "The lumpy aborted bodies form when this fungus parasitizes honey mushrooms, the opposite of what mycologists long believed.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "The normal (un-aborted) grey form closely resembles other pink-spored Entoloma species, several of which, such as Entoloma sinuatum (E. lividum), cause severe poisoning; the aborted lumps can also be confused with other pale fungi. Never eat any wild mushroom unless an expert confirms it.", "region": "Hardwood and mixed forests of southern and central Ontario", "angling": ""},
  {"id": "wine-cap-stropharia", "name": "Wine Cap (King Stropharia)", "sci": "Stropharia rugosoannulata", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Cap 5-15 cm wide (occasionally to 30 cm); stout stem 8-15 cm tall", "habitat": "Wood-chip mulch, garden beds, landscaped areas, and disturbed ground rich in decaying wood.", "tips": "Wine-red to reddish-brown cap fading to buff with age; thick white stem bearing a distinctive thick, wrinkled ring that is grooved and star-shaped (cog-wheel) on its underside; gills pale grey aging to dark purple-brown, with a dark purple-brown spore print.", "fact": "Easy to cultivate in wood-chip beds, it is nicknamed the 'garden giant' and is often grown alongside vegetables.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "Dark-spored, brown-gilled mushrooms can be confused with the deadly Galerina marginata (smaller, rusty-brown spores, growing on wood) and with toxic Cortinarius or Agaricus species that share mulch and lawns; the ringed stem alone is not a safe guarantee. Never eat any wild mushroom unless an expert confirms it.", "region": "Mulched gardens and landscaped areas of southern and central Ontario", "angling": ""},
  {"id": "angel-wings", "name": "Angel Wings", "sci": "Pleurocybella porrigens", "cat": "fungi", "sub": "poisonous", "emoji": "🪽", "size": "Fan-shaped caps 2-10 cm across, thin", "habitat": "On dead conifer wood, especially hemlock and other conifer logs and stumps.", "tips": "Pure white, thin, fan- or petal-shaped caps with essentially no stalk and crowded white gills, in overlapping clusters on conifer wood. Dangerously similar to edible oyster mushrooms, which grow mainly on hardwood and are thicker and greyer.", "fact": "Eaten for generations as 'angel wings,' it abruptly caused an outbreak of fatal brain disease in Japan in 2004, sickening 59 people and killing 17.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Do not eat. Formerly treated as edible, but implicated in fatal acute encephalopathy (brain damage), especially in people with kidney disease; the toxin is not fully understood and it is now considered unsafe. Closely resembles edible oyster mushrooms, which grow mainly on hardwood.", "region": "Central and northern Ontario conifer forests", "angling": ""},
  {"id": "brown-roll-rim", "name": "Brown Roll-rim", "sci": "Paxillus involutus", "cat": "fungi", "sub": "poisonous", "emoji": "💀", "size": "Cap 4-12 cm; stalk short and stout", "habitat": "Mycorrhizal, especially with birch; also conifers, in woods, parks and disturbed ground.", "tips": "Yellow-brown to olive-brown funnel-shaped cap with a strongly inrolled (rolled-under) margin, and crowded decurrent gills that bruise rusty-brown when handled; grows on the ground, often near birch.", "fact": "Long eaten in parts of Europe, it was only recognised in the 20th century to cause a delayed, potentially fatal autoimmune reaction that destroys red blood cells.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "DEADLY. Can trigger a delayed autoimmune reaction (Paxillus syndrome) that destroys red blood cells and leads to kidney failure; the risk builds unpredictably after repeated meals and cooking does not make it safe. Easily mistaken for edible brown mushrooms. Do not eat.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "eastern-american-panthercap", "name": "Eastern American Panthercap", "sci": "Amanita multisquamosa", "cat": "fungi", "sub": "poisonous", "emoji": "🍄", "size": "Cap 4-10 cm; stalk to 12 cm with a rimmed bulbous base", "habitat": "Mycorrhizal in mixed and oak-pine woods; on the ground.", "tips": "White to pale grey cap dotted with white pyramidal warts, white gills, a ring on the stalk, and a swollen base topped by a distinct funnel-like collar or roll of tissue. This is the true eastern North American 'panther cap'; the European Amanita pantherina does not occur here.", "fact": "Its neurotoxins (ibotenic acid and muscimol) are often more concentrated than in the related fly agaric, so poisonings tend to be more severe.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Toxic. Contains the isoxazole neurotoxins ibotenic acid and muscimol, causing delirium, agitation, nausea and seizures within about 1-3 hours; rarely fatal but seriously poisonous and often stronger than fly agaric. Do not eat.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "white-fibrecap", "name": "White Fibrecap", "sci": "Inocybe geophylla", "cat": "fungi", "sub": "poisonous", "emoji": "🍄", "size": "Cap 1-3 cm, small and conical", "habitat": "On soil in mixed and conifer woods, along paths and trail edges.", "tips": "Small silky white (sometimes lilac-tinged) conical to umbonate cap that splits radially with age, an earthy or spermatic smell, and a dull brown spore print. One of a huge genus (Inocybe) best avoided entirely.", "fact": "Together with the fool's funnel it is a leading source of muscarine poisoning, packed into a mushroom barely bigger than a thumbnail.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Toxic and potentially fatal. Like most Inocybe, it is rich in muscarine, causing rapid sweating, drooling, tearing and a dangerously slow heart within 15-30 minutes. Small brown or white 'little brown mushrooms' like this should never be eaten. Do not eat.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "yellow-staining-mushroom", "name": "Yellow-staining Mushroom", "sci": "Agaricus xanthodermus", "cat": "fungi", "sub": "poisonous", "emoji": "🟡", "size": "Cap 5-15 cm, white, often flat-topped", "habitat": "Lawns, gardens, parks, meadows, hedgerows and woodland edges; on the ground.", "tips": "White cap and stalk that instantly stain bright chrome-yellow when the base is cut or bruised, with an unpleasant phenol, ink or iodine smell that intensifies on cooking. Pink-then-brown gills like edible Agaricus, but the yellow base is the giveaway.", "fact": "It is the commonest cause of poisoning among the button-mushroom relatives, betraying itself with a chemical ink-like smell and a flash of yellow at the stem base.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "Toxic (gastrointestinal). Causes cramps, vomiting and diarrhea; easily confused with edible field and button mushrooms. If a white mushroom stains chrome-yellow at the cut base and smells of ink or phenol, discard it. Do not eat.", "region": "Southern Ontario, in lawns, gardens and parks", "angling": ""},
  {"id": "fools-funnel", "name": "Fool's Funnel", "sci": "Clitocybe dealbata", "cat": "fungi", "sub": "poisonous", "emoji": "🍄", "size": "Cap 2-4 cm, small", "habitat": "Grassy areas, lawns and path edges, often growing in rings.", "tips": "Small chalky white to buff funnel-shaped cap with crowded whitish decurrent gills, growing in grass and often in rings; also called the ivory funnel.", "fact": "Its muscarine can trigger drenching sweats, streaming eyes and drooling within half an hour, the classic 'SLUDGE' syndrome.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "Toxic and potentially fatal. Contains muscarine, causing rapid sweating, salivation, tearing, blurred vision, vomiting and a slowed heartbeat within 15-30 minutes (treatable with atropine). Grows in lawns among the edible fairy-ring mushroom (Marasmius oreades), a dangerous mix-up. Do not eat.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "deadly-webcap", "name": "Deadly Webcap", "sci": "Cortinarius rubellus", "cat": "fungi", "sub": "poisonous", "emoji": "💀", "size": "Cap 3-8 cm, conical then umbonate", "habitat": "Boreal conifer forest with spruce, on damp, mossy, acidic ground.", "tips": "Tawny orange-brown conical cap with a pointed central bump, rusty-brown gills and a rusty spore print, and a fibrous cobweb-like veil (cortina) on the stalk; grows with spruce.", "fact": "Its toxin, orellanine, gives no warning for days to weeks before silently destroying the kidneys.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "rare", "status": "Not at risk", "atRisk": false, "caution": "DEADLY. Contains orellanine, which attacks the kidneys after a deceptive delay of 2 days to 3 weeks; irreversible kidney failure can follow, sometimes requiring dialysis or a transplant. No taste or early symptom warns you. Never eat any webcap (Cortinarius).", "region": "Northern Ontario boreal conifer forests (rare and local)", "angling": ""},
  {"id": "birds-nest-fungus", "name": "Common Bird's Nest Fungus", "sci": "Crucibulum laeve", "cat": "fungi", "sub": "other-fungi", "emoji": "🪺", "size": "Cup-shaped nests 5-10 mm wide", "habitat": "On wood chips, mulch, fallen twigs, and rotting wood, often in mulched gardens and trails.", "tips": "Tiny cups like miniature nests, tan and cottony outside, each holding several disc-like 'eggs' (peridioles) when mature.", "fact": "The tiny eggs are spore packets that raindrops splash out of the cup, which works as a natural splash-cup launching them up to a metre away.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Too small and tough to eat; harmless.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "dead-mans-fingers", "name": "Dead Man's Fingers", "sci": "Xylaria polymorpha", "cat": "fungi", "sub": "other-fungi", "emoji": "🖐️", "size": "Club-shaped fingers 3-8 cm tall, often in small clusters", "habitat": "In clusters on hardwood stumps and buried roots, especially beech and maple.", "tips": "Erect, finger- or club-shaped fruitbodies, pale blue-grey when young then blackened and warty outside, with tough white flesh inside.", "fact": "Named for the way its blackened clubs push up from buried wood like stiff fingers reaching out of a grave.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Inedible - tough and woody. Not a food species, though harmless to handle.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "witchs-butter", "name": "Witch's Butter", "sci": "Tremella mesenterica", "cat": "fungi", "sub": "other-fungi", "emoji": "🧈", "size": "Gelatinous folded masses 2-7 cm across", "habitat": "On dead hardwood branches and twigs, often appearing after rain or during mild winter thaws.", "tips": "Bright golden-yellow to orange, brain-like gelatinous folds that swell and shine when wet and shrink to a hard, dark crust when dry.", "fact": "Despite sitting on branches, it does not eat the wood - it is a parasite on the crust fungi (Peniophora) living inside it.", "seasons": ["fall", "winter", "spring"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Reported as edible but flavourless and gelatinous, and rarely worth eating. Its yellow/orange jelly look-alikes (Dacrymyces, Tremella aurantia) are also non-toxic, and there are no deadly yellow-jelly look-alikes - but never eat any wild mushroom unless an expert has confirmed it is safe.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "wolfs-milk-slime", "name": "Wolf's Milk Slime", "sci": "Lycogala epidendrum", "cat": "fungi", "sub": "other-fungi", "emoji": "🐺", "size": "Pink to grey balls 3-15 mm across, in groups", "habitat": "On damp, well-rotted logs and stumps in shaded forest.", "tips": "Small salmon-pink to greyish spheres on wood; young ones ooze a pink paste when squeezed, while older ones dry to a dusty grey spore mass.", "fact": "It is a slime mould, not a true fungus, and can actually creep slowly across wood before forming its pink cushions.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "A slime mould, not a fungus, and not a food species.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "cinnabar-red-polypore", "name": "Cinnabar-red Polypore", "sci": "Pycnoporus cinnabarinus", "cat": "fungi", "sub": "other-fungi", "emoji": "🟠", "size": "Bracket 2-13 cm wide", "habitat": "On dead hardwood branches and logs, especially cherry and birch.", "tips": "A vivid cinnabar orange-red bracket that is the same bright colour on top and on the pored underside; it fades with age but stays reddish.", "fact": "Its orange-red pigment, cinnabarin, has antibacterial properties and readily stains whatever it touches.", "seasons": ["summer", "fall", "winter"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Inedible - tough and corky; not a food species.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "scarlet-elf-cup", "name": "Scarlet Elf Cup", "sci": "Sarcoscypha austriaca", "cat": "fungi", "sub": "other-fungi", "emoji": "🥣", "size": "Shallow cups 1-5 cm across on a short stalk", "habitat": "On damp, mossy fallen hardwood sticks in rich, moist woods, appearing in early spring as snow melts.", "tips": "Shallow, brilliant scarlet cups with a whitish, minutely hairy outer surface on a short pale stalk; separating it from close relatives needs a microscope.", "fact": "When warmed by breath or sun, the ripe cups puff out a visible cloud of spores, sometimes with a faint hiss.", "seasons": ["winter", "spring"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Considered non-toxic but thin, tough, and of little food value; the closely related scarlet cups (all non-toxic) can only be separated under a microscope. Never eat any wild mushroom unless an expert has confirmed it is safe.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "chicken-of-the-woods", "name": "Chicken of the Woods", "sci": "Laetiporus sulphureus", "cat": "fungi", "sub": "edible", "emoji": "🍗", "size": "Overlapping shelves 5-30 cm wide; clusters to 50 cm", "habitat": "On living and dead hardwoods, especially oak; a wood-rotting bracket.", "tips": "Bright sulphur-yellow to orange overlapping shelves with a soft, suede texture and no gills - fine pores underneath.", "fact": "Its bright flesh and meaty texture earn the nickname 'chicken,' and it can regrow on the same log for years.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Can cause stomach upset in some people, and specimens on conifers or eucalyptus should be avoided; it has look-alikes. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "dryads-saddle", "name": "Dryad's Saddle (Pheasant Back)", "sci": "Cerioporus squamosus", "cat": "fungi", "sub": "edible", "emoji": "🐴", "size": "Fan- or saddle-shaped bracket 8-30 cm across", "habitat": "On living and dead hardwoods, especially dead elm, maple, and box elder; a wound and wood-rot fungus, mainly in spring.", "tips": "Tan cap patterned with concentric brown feather-like scales ('pheasant back'), a short blackening stalk, and large angular white pores beneath; smells of watermelon rind.", "fact": "One of the first brackets of spring, appearing alongside the morels; only the tender growing edge is worth eating as it quickly turns corky.", "seasons": ["spring", "summer"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Edible only when very young and tender, and it has other polypore look-alikes. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "giant-puffball", "name": "Giant Puffball", "sci": "Calvatia gigantea", "cat": "fungi", "sub": "edible", "emoji": "⚪", "size": "15-50+ cm across; can exceed a basketball and 20 kg", "habitat": "Meadows, pastures, roadsides, and open woods on rich soil.", "tips": "A smooth white ball with no stalk, cap, or gills; the interior is firm and pure white when edible (yellow or brown means it is spent).", "fact": "A single giant puffball can hold several trillion spores - enough that if all grew, the offspring would outweigh the Earth.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Deadly young Amanita 'button' stages can resemble small puffballs; always slice vertically to confirm uniform solid white flesh with no gill outline. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "golden-chanterelle", "name": "Golden Chanterelle", "sci": "Cantharellus cibarius", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Funnel-shaped, cap 3-10 cm across, 4-12 cm tall", "habitat": "Mossy ground under hardwoods and conifers, often oak, birch, and pine; mycorrhizal.", "tips": "Egg-yellow throughout, with blunt, forking false gills (ridges) that run down the stalk rather than sharp blades; smells faintly of apricot.", "fact": "Chanterelles resist cultivation because they depend on a living tree partnership, so nearly all are wild-foraged.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Has toxic look-alikes, notably the jack-o'-lantern (Omphalotus illudens) and false chanterelle. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "king-bolete", "name": "King Bolete (Porcini)", "sci": "Boletus edulis", "cat": "fungi", "sub": "edible", "emoji": "🍄‍🟫", "size": "Cap 8-25 cm across on a stout stalk", "habitat": "Mycorrhizal with conifers and hardwoods; mossy woodland edges and trails.", "tips": "Brown bun-shaped cap, a fat pale stalk with a fine raised net, and a sponge of white-to-olive pores (never red); flesh does not stain blue.", "fact": "The porcini of European cuisine; Ontario's woods produce closely related king boletes prized for drying.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Some boletes are toxic - avoid any with red pores or blue-staining, bitter flesh. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "oyster-mushroom", "name": "Oyster Mushroom", "sci": "Pleurotus ostreatus", "cat": "fungi", "sub": "edible", "emoji": "🦪", "size": "Caps 5-25 cm across in overlapping clusters", "habitat": "On dead and dying hardwoods, especially poplar, beech, and maple.", "tips": "Shelving fan- or oyster-shaped caps, white to tan, with gills running down a short off-centre or absent stalk.", "fact": "Oyster mushrooms are carnivorous - their mycelium paralyzes and digests tiny roundworms to obtain nitrogen.", "seasons": ["spring", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Toxic look-alikes include the orange jack-o'-lantern, the mock oyster (Phyllotopsis) and, most dangerous, the pure-white Angel Wings (Pleurocybella porrigens), which grows on conifers and has caused fatalities. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "shaggy-mane", "name": "Shaggy Mane", "sci": "Coprinus comatus", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Cylindrical cap 4-15 cm tall", "habitat": "Disturbed ground - lawns, gravel, roadsides, and wood-chip beds.", "tips": "Tall white cylindrical cap with shaggy, upturned scales that dissolves into black 'ink' from the bottom up within a day.", "fact": "Shaggy manes self-digest into inky black liquid so fast they must be eaten within hours of picking.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Easily confused with other inky caps; the related Coprinopsis atramentaria causes severe illness if eaten with alcohol. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "yellow-morel", "name": "Yellow Morel", "sci": "Morchella americana", "cat": "fungi", "sub": "edible", "emoji": "🍄‍🟫", "size": "Honeycombed cap 4-12 cm tall", "habitat": "Under dead or dying elm and ash, in old apple orchards, and on recently burned ground.", "tips": "Pitted, honeycombed cap fully attached to the stalk and completely hollow when sliced top to bottom - the key separator from false morels.", "fact": "Morels often flush in huge numbers the spring after a forest fire or when elms die.", "seasons": ["spring"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "The toxic false morel (Gyromitra) is a look-alike; true morels are hollow throughout and must be thoroughly cooked. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "black-trumpet", "name": "Black Trumpet", "sci": "Craterellus fallax", "cat": "fungi", "sub": "edible", "emoji": "🎺", "size": "Trumpet 3-8 cm tall, 1-6 cm wide", "habitat": "In moss and leaf litter under hardwoods, often beech and oak.", "tips": "Thin, hollow, grey-black funnel with no distinct gills - a wavy vase easily overlooked against dark leaf litter.", "fact": "Also called the 'horn of plenty,' its dark colour makes it one of the most camouflaged and overlooked edibles.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Easily confused with other dark funnel fungi. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "hen-of-the-woods", "name": "Hen of the Woods (Maitake)", "sci": "Grifola frondosa", "cat": "fungi", "sub": "edible", "emoji": "🍄", "size": "Clustered rosette 15-60 cm across, up to several kg", "habitat": "At the base of oaks and other hardwoods, fruiting from the roots.", "tips": "A grey-brown rosette of many small, spoon-shaped caps arising from one branched base; grey above with a white pore surface below.", "fact": "Prized in Japan as maitake, the 'dancing mushroom'; a single cluster can weigh over 20 kg.", "seasons": ["fall"], "activity": "varies", "seen": "uncommon", "status": "Common", "atRisk": false, "caution": "Has bracket look-alikes such as Berkeley's polypore. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "lions-mane", "name": "Lion's Mane", "sci": "Hericium erinaceus", "cat": "fungi", "sub": "edible", "emoji": "🦁", "size": "Cushiony white mass 8-25 cm across", "habitat": "On wounds and dead spots of living hardwoods, especially beech, maple, and oak.", "tips": "A single unbranched white cushion covered in soft, downward-hanging spines (teeth) 1-4 cm long, with no cap or gills; yellows and browns with age.", "fact": "A gourmet and medicinal mushroom studied for nerve-growth compounds; its seafood-like texture earns the nickname 'poor man's crab.'", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "One of the safest wild mushrooms to identify - its toothed relatives (Hericium americanum, H. coralloides) are also edible - but never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "lobster-mushroom", "name": "Lobster Mushroom", "sci": "Hypomyces lactifluorum", "cat": "fungi", "sub": "edible", "emoji": "🦞", "size": "Transformed host 5-15 cm across", "habitat": "On the ground in mixed woods where its Russula and Lactarius hosts grow.", "tips": "Not a true mushroom but a mould that coats a host, turning it hard, bright orange, and seafood-scented, with distorted, gill-less form.", "fact": "The 'lobster' is really a parasitic fungus (Hypomyces) overtaking another mushroom, colour and all.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Safe only when the host beneath the orange crust is a benign Russula or Lactarius; unknown hosts can be toxic. Never eat any wild mushroom unless an expert has confirmed the identification with certainty.", "region": "Central and northern Ontario", "angling": ""},
  {"id": "deadly-galerina", "name": "Deadly Galerina", "sci": "Galerina marginata", "cat": "fungi", "sub": "poisonous", "emoji": "💀", "size": "Small brown cap 1.5-4 cm across", "habitat": "On rotting conifer and hardwood logs and wood chips.", "tips": "Small brown cap, rusty-brown spores, a fragile ring on the stalk, growing in groups on wood.", "fact": "This drab little brown mushroom on wood is as deadly as the death cap, sharing the same amatoxins.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "DEADLY. Contains the same amatoxins as the death cap and grows on wood, where it is easily mistaken for edible wood mushrooms and honey mushrooms. Do not eat.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "destroying-angel", "name": "Destroying Angel", "sci": "Amanita bisporigera", "cat": "fungi", "sub": "poisonous", "emoji": "💀", "size": "Cap 5-12 cm; stalk to 15 cm with a sac-like volva", "habitat": "Mycorrhizal in mixed and hardwood forests; on the ground in summer and fall.", "tips": "Pure white all over - cap, gills, and stalk - with a skirt-like ring and a sac-like cup (volva) at the swollen base.", "fact": "Responsible for a large share of fatal mushroom poisonings worldwide; there is no reliable home antidote.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "DEADLY. Contains amatoxins that cause fatal liver and kidney failure; a single cap can kill an adult. Symptoms are delayed 6-24 hours, giving false reassurance. Never eat and never taste-test.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "false-morel", "name": "False Morel", "sci": "Gyromitra esculenta", "cat": "fungi", "sub": "poisonous", "emoji": "🧠", "size": "Cap 4-12 cm, reddish-brown, brain-like", "habitat": "Sandy soil under conifers, often pine, in spring.", "tips": "Reddish-brown, wrinkled, brain- or saddle-shaped cap (not pitted like a honeycomb) that is chambered and cottony inside, not cleanly hollow.", "fact": "Eaten in some cultures after special preparation, yet its toxin is the same class used in rocket fuel and it still causes deaths.", "seasons": ["spring"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Toxic and potentially deadly. Contains gyromitrin, which converts to monomethylhydrazine and can cause liver failure and death, even from inhaling cooking vapours. Do not eat.", "region": "Central and northern Ontario", "angling": ""},
  {"id": "fly-agaric", "name": "Fly Agaric", "sci": "Amanita muscaria", "cat": "fungi", "sub": "poisonous", "emoji": "🍄", "size": "Cap 8-20 cm, red to orange with white warts", "habitat": "Mycorrhizal with birch, pine, and spruce; common in mixed forest.", "tips": "Iconic scarlet-to-orange cap dotted with white wart-like patches, white gills, a ring, and a bulbous, ringed base.", "fact": "The classic red-and-white toadstool of fairy tales; historically steeped in milk as an insecticide.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Toxic. Ibotenic acid and muscimol cause delirium, nausea, and seizures; rarely fatal but seriously poisoning. Do not eat.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "sulphur-tuft", "name": "Sulphur Tuft", "sci": "Hypholoma fasciculare", "cat": "fungi", "sub": "poisonous", "emoji": "🟡", "size": "Caps 2-6 cm in dense clusters", "habitat": "In large clusters on dead hardwood and conifer stumps, logs, and buried roots.", "tips": "Sulphur-yellow to tawny caps with a greenish tinge, crowded olive-green to purple-brown gills, and intensely bitter flesh; grows in crowded tufts on wood.", "fact": "One of the most common wood-rotting mushrooms in Ontario forests, fruiting in large showy clusters through much of the year.", "seasons": ["spring", "summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Toxic. Contains fasciculol and steroid toxins causing vomiting, diarrhea, and possible liver damage; its wood-clustering habit is easily confused with edible honey mushrooms. Do not eat.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "green-spored-parasol", "name": "Green-spored Parasol", "sci": "Chlorophyllum molybdites", "cat": "fungi", "sub": "poisonous", "emoji": "🍄", "size": "Cap 7-30 cm on a tall stalk", "habitat": "Lawns, parks, and grassy areas after warm summer rains.", "tips": "Large white parasol with brownish scales and a ring; the mature gills and spore print turn dull green - the giveaway.", "fact": "The single most frequent cause of mushroom poisoning calls in North America, thanks to its lawn habit.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "Toxic - the most common cause of mushroom poisoning in North America. Causes violent vomiting and diarrhea; mimics edible parasols and puffballs on lawns. Do not eat.", "region": "Southern Ontario", "angling": ""},
  {"id": "jack-o-lantern", "name": "Jack-o'-Lantern Mushroom", "sci": "Omphalotus illudens", "cat": "fungi", "sub": "poisonous", "emoji": "🎃", "size": "Caps 5-20 cm in dense clusters", "habitat": "In dense clusters on hardwood stumps, roots, and buried wood.", "tips": "Orange throughout, clustered on wood, with true sharp gills (not chanterelle ridges); the gills glow faint green in the dark.", "fact": "Its gills glow with a soft green bioluminescence (foxfire), visible in a fully dark room.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Common", "atRisk": false, "caution": "Toxic. Causes severe cramps, vomiting, and diarrhea; frequently mistaken for the edible golden chanterelle. Do not eat.", "region": "Southern and central Ontario", "angling": ""},
  {"id": "death-cap", "name": "Death Cap", "sci": "Amanita phalloides", "cat": "fungi", "sub": "poisonous", "emoji": "💀", "size": "Cap 5-15 cm, greenish, with a volva at the base", "habitat": "Under introduced and ornamental trees (oak, chestnut, hornbeam) in urban and planted settings.", "tips": "Greenish to yellowish cap with white gills, a ring on the stalk, and a prominent cup-like volva at the base.", "fact": "Blamed for the majority of fatal mushroom poisonings globally; its toxins survive cooking, drying, and freezing.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "rare", "status": "Introduced", "atRisk": false, "caution": "DEADLY. The world's most lethal mushroom; amatoxins cause fatal organ failure after a deceptive symptom-free delay. Introduced to Ontario with ornamental trees. Never eat.", "region": "Southern Ontario, urban and planted areas", "angling": ""},
  {"id": "artists-conk", "name": "Artist's Conk", "sci": "Ganoderma applanatum", "cat": "fungi", "sub": "other-fungi", "emoji": "🎨", "size": "Woody bracket 10-60+ cm wide", "habitat": "On living and dead hardwoods; a perennial shelf.", "tips": "Hard, flat, grey-brown woody shelf; the white pore surface bruises brown instantly, so it can be drawn on.", "fact": "The instantly bruising pore surface has been used as a natural drawing canvas for centuries.", "seasons": ["spring", "summer", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "", "region": "Widespread across Ontario", "angling": ""},
  {"id": "bracket-shelf-fungi", "name": "Bracket & Shelf Fungi", "sci": "Polyporales spp.", "cat": "fungi", "sub": "other-fungi", "emoji": "🪵", "size": "Ranges widely, a few cm to over 50 cm across", "habitat": "On living trunks, dead logs, and stumps throughout Ontario forests.", "tips": "A broad group of stalkless, tough or woody, shelf-forming polypores with pores (not gills) beneath; key wood-recyclers.", "fact": "Bracket fungi are the forest's recyclers, breaking down the lignin in wood that few other organisms can digest.", "seasons": ["summer", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "", "region": "Widespread across Ontario", "angling": ""},
  {"id": "british-soldiers-lichen", "name": "British Soldiers Lichen", "sci": "Cladonia cristatella", "cat": "fungi", "sub": "other-fungi", "emoji": "🪖", "size": "Stalks 1-2 cm tall with red caps", "habitat": "On rotting wood, stumps, mossy logs, and sandy soil.", "tips": "Tiny grey-green stalks (podetia), each tipped with a bright red cap - the 'red coats' that give the lichen its name.", "fact": "A lichen is two organisms - a fungus and an alga - living as one; the red tips are the fungal spore cups.", "seasons": ["spring", "summer", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "", "region": "Widespread across Ontario", "angling": ""},
  {"id": "coral-fungi", "name": "Coral Fungi", "sci": "Ramaria spp.", "cat": "fungi", "sub": "other-fungi", "emoji": "🪸", "size": "Branched clusters 3-20 cm tall", "habitat": "On the forest floor and on rotting wood in shaded woods.", "tips": "Upright, branched, coral- or antler-like fruitbodies in white, tan, yellow, or pink, with no cap or gills.", "fact": "Their branching shapes mimic ocean coral, yet they are land fungi that decay wood and leaf litter.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "Several coral fungi (some Ramaria) are mildly toxic and act as laxatives; not recommended for eating without expert species-level identification.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "honey-mushroom", "name": "Honey Mushroom", "sci": "Armillaria mellea", "cat": "fungi", "sub": "other-fungi", "emoji": "🍯", "size": "Caps 3-15 cm in dense clusters", "habitat": "In clusters at the base of trees, stumps, and buried roots.", "tips": "Honey-coloured caps in dense clusters, a ring on the stalk, white spores, and black 'bootlace' rhizomorphs under the host's bark.", "fact": "Related Armillaria form some of Earth's largest organisms - one in Oregon spans over 9 square kilometres.", "seasons": ["fall"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "A plant pathogen that causes Armillaria root rot; note that the DEADLY Galerina marginata shares the same wood-clustering habit and is easily confused with it.", "region": "Widespread across Ontario", "angling": ""},
  {"id": "red-belted-polypore", "name": "Red-belted Polypore", "sci": "Fomitopsis pinicola", "cat": "fungi", "sub": "other-fungi", "emoji": "🍄‍🟫", "size": "Hoof- to shelf-shaped bracket 5-30 cm wide", "habitat": "On dead conifers and hardwoods; a perennial shelf.", "tips": "Hard hoof- or shelf-shaped bracket with a reddish band near the margin, a crusted top, and a cream pore underside.", "fact": "A major decomposer that produces a brown cubical rot, recycling fallen conifers back into soil.", "seasons": ["spring", "summer", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "", "region": "Central and northern Ontario", "angling": ""},
  {"id": "turkey-tail", "name": "Turkey Tail", "sci": "Trametes versicolor", "cat": "fungi", "sub": "other-fungi", "emoji": "🦃", "size": "Thin brackets 2-8 cm wide in tiers", "habitat": "On dead hardwood logs, stumps, and branches; extremely common.", "tips": "Thin, flexible, concentrically banded multicoloured brackets with a velvety top and a whitish surface of tiny pores beneath.", "fact": "One of the most studied medicinal fungi; its compound PSK is used as an approved cancer-therapy adjuvant in Japan.", "seasons": ["summer", "fall", "winter"], "activity": "varies", "seen": "common", "status": "Common", "atRisk": false, "caution": "", "region": "Widespread across Ontario", "angling": ""},
  {"id": "chaga", "name": "Chaga", "sci": "Inonotus obliquus", "cat": "fungi", "sub": "other-fungi", "emoji": "🟤", "size": "Irregular black conk 10-40 cm across", "habitat": "A sterile canker almost always on living birch.", "tips": "A hard, charcoal-black, cracked mass bursting from birch bark, rusty-orange and corky inside.", "fact": "Chaga is a long-lived birch parasite harvested for tea; it regrows slowly, so sustainable harvest matters.", "seasons": ["spring", "summer", "fall", "winter"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Central and northern Ontario", "angling": ""},
  {"id": "earthstar", "name": "Earthstar", "sci": "Geastrum spp.", "cat": "fungi", "sub": "other-fungi", "emoji": "⭐", "size": "2-10 cm across when the rays open", "habitat": "On the ground in leaf litter and sandy soil under trees.", "tips": "A puffball whose outer skin splits into pointed rays that peel back like a star, lifting a central spore sac.", "fact": "When raindrops strike the central sac it puffs out spores, and the star's arms even flex with changing humidity.", "seasons": ["fall", "winter"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""},
  {"id": "hemlock-varnish-shelf", "name": "Hemlock Varnish Shelf (Reishi)", "sci": "Ganoderma tsugae", "cat": "fungi", "sub": "other-fungi", "emoji": "🔴", "size": "Kidney-shaped shelf 5-30 cm wide, often with a lacquered stalk", "habitat": "On dead conifers, especially eastern hemlock stumps and logs.", "tips": "A shiny, varnished-looking red-brown to mahogany shelf with a pale yellow-white margin and a white pore surface; young flesh is corky and the surface looks lacquered.", "fact": "The Ontario relative of the famed Asian reishi (lingzhi), long dried and brewed as a medicinal tea for its triterpene compounds.", "seasons": ["summer", "fall"], "activity": "varies", "seen": "uncommon", "status": "Native", "atRisk": false, "caution": "", "region": "Southern and central Ontario", "angling": ""}
